   cap=cv2.VideoCapture(str(src));assert cap.isOpened();fps=cap.get(cv2.CAP_PROP_FPS);n=int(cap.get(cv2.CAP_PROP_FRAME_COUNT));assert n==rec['n_frames'] and abs(fps-rec['fps'])<1e-4
